<?php namespace DomainSystem\Plugins\settings\Repositories; use DomainSystem\Plugins\Database\Connection; use DomainSystem\Plugins\settings\Contracts\SettingRepositoryInterface; class SettingRepository implements SettingRepositoryInterface { private \PDO $db; public function __construct(Connection $connection) { $this->db = $connection->getPdo(); } public function getAll(): array { $stmt = $this->db->query("SELECT * FROM settings"); return $stmt->fetchAll(\PDO::FETCH_ASSOC); } public function upsert(string $key, string $value): void { $stmt = $this->db->prepare("INSERT INTO settings (key_name, key_value) VALUES (:k, :v) ON DUPLICATE KEY UPDATE key_value = VALUES(key_value)"); $stmt->execute([":k" => $key, ":v" => $value]); } }
